const BASE = 'https://api.lokalise.com/api2';
const PIDS = [
  { name: 'Personality.co', pid: '31393214664f295f94dd86.76792605' },
  { name: 'Members area', pid: '9933660066825e9a8005c8.58526829' }
];
const out = [];
for (const p of PIDS) {
  out.push({ json: { name: p.name, pid: p.pid, kind: 'statuses', url: BASE + '/projects/' + p.pid + '/custom-translation-statuses' } });
  out.push({ json: { name: p.name, pid: p.pid, kind: 'project', url: BASE + '/projects/' + p.pid } });
}
return out;

const items = $input.all();
const cfgs = $('Config').all().map(c => c.json);
const out = [];
for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const b = r.body !== undefined ? r.body : r;
  const cfg = cfgs[i];
  if (cfg.kind === 'statuses') {
    out.push({ json: { name: cfg.name, kind: 'statuses', statusCode: r.statusCode,
      statuses: Array.isArray(b.custom_translation_statuses)
        ? b.custom_translation_statuses.map(s => ({ id: s.status_id, title: s.title, color: s.color }))
        : JSON.stringify(b).slice(0, 300) } });
  } else {
    const p = b.project || b;
    const s = p.settings || {};
    out.push({ json: { name: cfg.name, kind: 'project', statusCode: r.statusCode,
      custom_translation_statuses: s.custom_translation_statuses,
      reviewing: s.reviewing, auto_toggle_unverified: s.auto_toggle_unverified,
      key_editing: s.key_editing, segmentation: s.segmentation, branching: s.branching } });
  }
}
return out;
